 for(const [n,r,t] of [[1000,10,3],[200,50,4],[500,20,2],[2400,25,2]])put('growth',`A fictional population of ${n} grows by ${r} percent per year with no limits. Using N = N0 × (1 + r)^t, how many individuals are there after ${t} years?${N}`,r4(n*(1+r/100)**t),board('Fictional exponential growth',[`N0 = ${n}`,`growth = ${r} percent per year`,`t = ${t} years`]),`Multiply by ${r4(1+r/100)} each year for ${t} years: ${n} × ${r4(1+r/100)}^${t} = ${r4(n*(1+r/100)**t)}.`);
 for(const [b,d,i,e,p] of [[800,500,0,100,10000],[1500,1100,400,300,40000],[60,90,10,5,3000],[210,150,45,15,6000]])put('growth',`A fictional town of ${p} people had ${b} births, ${d} deaths, ${i} immigrants and ${e} emigrants in one year. What is the population growth rate as a percent? Use a negative number for a decrease.${N}`,r4((b-d+i-e)/p*100),board('Fictional town',[`population = ${p}`,`births ${b}, deaths ${d}`,`immigrants ${i}, emigrants ${e}`]),`Net change = ${b} − ${d} + ${i} − ${e} = ${b-d+i-e}. Growth rate = ${b-d+i-e} ÷ ${p} × 100 = ${r4((b-d+i-e)/p*100)} percent.`);
