 for(const [n,r,k] of [[100,0.5,1000],[500,0.4,1000]]){const n1=n+r*n*(k-n)/k,n2=n1+r*n1*(k-n1)/k;put('growth',`A fictional population starts at ${n} with r = ${r} per year and K = ${k}. Using logistic growth for two successive years, where each year adds r × N × (K − N) ÷ K, what is the population after two years?${N}`,r4(n2),board('Fictional logistic population',[`N0 = ${n}, r = ${r}, K = ${k}`,'apply the rule twice','find N after year 2']),`Year 1 adds ${r4(r*n*(k-n)/k)}, so N1 = ${r4(n1)}. Year 2 adds ${r4(r*n1*(k-n1)/k)}, so N2 = ${r4(n2)}.`);}
 for(const [a,b,c] of [[2200,1900,900],[900,1500,1600],[480,850,670]])put('agestr',`A fictional country counts ${a} thousand people aged 0 to 14, ${b} thousand aged 15 to 44 and ${c} thousand aged 45 and older. What percent of the people are aged 0 to 14?${N}`,r4(a/(a+b+c)*100),bars('Fictional country (thousands)',['0–14','15–44','45+'],[a,b,c]),`The total is ${a} + ${b} + ${c} = ${a+b+c} thousand. Percent aged 0 to 14 = ${a} ÷ ${a+b+c} × 100 = ${r4(a/(a+b+c)*100)} percent.`);
